/**
 * @title Indian Rupee Token (INRT)
 * @author Expert Solidity Engineer
 * @notice An ERC20 token backed 1:1 by Indian Rupee reserves in a bank account.
 * It includes mechanisms for minting against bank deposits, burning for withdrawals,
 * and emergency pausable transfers. It is designed to work with the CryptoUPIHook
 * for processing withdrawals initiated via Uniswap v4.
 * @dev Inherits from OpenZeppelin's ERC20Pausable and Ownable contracts.
 */
contract INRT is ERC20Pausable, Ownable {
    using SafeMath for uint256;

    // --- State Variables ---

    /// @notice Tracks the total INR reserves held in the bank, in the smallest unit (paisa).
    uint256 public totalBankReserves;

    /// @notice Maps bank transaction IDs to a boolean indicating if they have been used for minting.
    mapping(bytes32 => bool) public processedBankTxs;

    /// @notice The authorized hook contract for processing withdrawals.
    address public hookContract;

    /// @notice Struct to hold details of a withdrawal request.
    struct WithdrawalRequest {
        address user;
        uint256 amount;
        string upiId;
        uint256 timestamp;
        bool processed;
    }

    /// @notice Maps a unique withdrawal ID to its data.
    mapping(uint256 => WithdrawalRequest) public withdrawalData;

    /// @notice Counter for generating unique withdrawal IDs.
    uint256 public nextWithdrawalId;

    // --- Events ---

    event TokensMinted(address indexed to, uint256 amount, bytes32 indexed bankTxId);
    event TokensBurned(address indexed from, uint256 amount, uint256 indexed withdrawalId);
    event WithdrawalRequested(uint256 indexed withdrawalId, address indexed user, uint256 amount, string upiId);
    event WithdrawalProcessed(uint256 indexed withdrawalId);
    event HookContractUpdated(address indexed newHook);

    // --- Modifiers ---

    /**
     * @dev Throws if the caller is not the owner or the authorized hook contract.
     */
    modifier onlyAuthorized() {
        require(owner() == _msgSender() || hookContract == _msgSender(), "INRT: Caller is not authorized");
        _;
    }

    // --- Constructor ---

    /**
     * @dev Initializes the contract. ERC20 constructor is called with empty strings
     * as name and symbol are hardcoded by overriding the respective functions.
     */
