        _pause();
    }

    /**
     * @notice Unpauses all token transfers. Can only be called by the owner.
     * @dev Emits an Unpaused event.
     */
    function unpause() public onlyOwner {
        _unpause();
    }

    // --- Hook Contract Management ---

    /**
     * @notice Sets or updates the authorized hook contract address.
     * @param _hook The address of the hook contract.
     */
    function setHook(address _hook) external onlyOwner {
        require(_hook != address(0), "INRT: Hook address cannot be zero");
        hookContract = _hook;
        emit HookContractUpdated(_hook);
    }

    /**
     * @notice Revokes the authorization of the current hook contract.
     */
    function revokeHook() external onlyOwner {
        emit HookContractUpdated(address(0));
        hookContract = address(0);
    }

    // --- Minting ---

    /**
     * @notice Mints new tokens and increases bank reserves. Only owner can call this.
     * @dev Requires a unique bank transaction ID to prevent double-counting deposits.
     * @param to The address to mint tokens to.
     * @param amount The amount of tokens to mint (in paisa).
     * @param bankTxId A unique identifier for the corresponding bank deposit.
     */
    function mint(address to, uint256 amount, bytes32 bankTxId) external onlyOwner {
        require(to != address(0), "INRT: Mint to the zero address");
        require(amount > 0, "INRT: Mint amount must be > 0");
        require(!processedBankTxs[bankTxId], "INRT: Bank transaction already processed");

        processedBankTxs[bankTxId] = true;
        totalBankReserves = totalBankReserves.add(amount);
        _mint(to, amount);

        emit TokensMinted(to, amount, bankTxId);
    }

    // --- Withdrawals and Burning ---

    /**
     * @notice Called by the authorized hook to finalize a withdrawal by burning its own tokens and logging the request.
     * @dev This is the second step in the hook-based withdrawal process. The hook first
     * transfers the user's tokens to itself, then calls this function.
     * @param user The original user requesting the withdrawal.
     * @param amount The amount of tokens to burn (in paisa).
     * @param upiId The user's UPI ID for the fiat payout.
     */
    function submitWithdrawal(address user, uint256 amount, string calldata upiId) external onlyAuthorized {
        require(user != address(0), "INRT: User address cannot be zero");
        require(amount > 0, "INRT: Withdrawal amount must be > 0");
        require(bytes(upiId).length > 0, "INRT: UPI ID cannot be empty");

        // Burn the tokens from the caller (the hook contract)
        _burn(_msgSender(), amount);

        // Decrease reserves and log the withdrawal request
        totalBankReserves = totalBankReserves.sub(amount);
        uint256 withdrawalId = nextWithdrawalId;
        withdrawalData[withdrawalId] = WithdrawalRequest({
            user: user,
            amount: amount,
            upiId: upiId,
            timestamp: block.timestamp,
            processed: false
        });

        emit WithdrawalRequested(withdrawalId, user, amount, upiId);
        emit TokensBurned(user, amount, withdrawalId);

        nextWithdrawalId++;
    }

    /**
     * @notice Marks a withdrawal request as processed after fiat has been sent.
     * @dev Can only be called by the owner.
     * @param withdrawalId The ID of the withdrawal to mark as processed.
     */
    function markWithdrawalAsProcessed(uint256 withdrawalId) external onlyOwner {
        WithdrawalRequest storage request = withdrawalData[withdrawalId];
        require(request.user != address(0), "INRT: Withdrawal does not exist");
        require(!request.processed, "INRT: Withdrawal already processed");

        request.processed = true;
        emit WithdrawalProcessed(withdrawalId);
    }

    // --- View Functions ---

    /**
     * @notice Returns the details of a specific withdrawal request.
     * @param withdrawalId The ID of the withdrawal request.
     * @return user The address of the user who made the request.
     * @return amount The amount of tokens withdrawn.
     * @return upiId The user's UPI ID.
     * @return timestamp The time the request was made.
     * @return processed Whether the fiat payout has been marked as completed.
     */
    function getWithdrawalDetails(uint256 withdrawalId)
        external
        view
        returns (address user, uint256 amount, string memory upiId, uint256 timestamp, bool processed)
    {
        WithdrawalRequest storage w = withdrawalData[withdrawalId];
        return (w.user, w.amount, w.upiId, w.timestamp, w.processed);
    }

    /**
     * @notice Checks if a bank transaction ID has already been used for minting.
     * @param bankTxId The bank transaction ID to check.
     * @return True if the ID has been processed, false otherwise.
     */
    function isBankTxIdProcessed(bytes32 bankTxId) external view returns (bool) {
        return processedBankTxs[bankTxId];
    }

    /**
     * @notice Calculates the backing ratio of the token.
     * @dev Returns the ratio as a fixed-point number with 18 decimals of precision.
     * A value of 1e18 means 100% backed.
     * @return The backing ratio (totalBankReserves / totalSupply).
     */
    function getBackingRatio() external view returns (uint256) {
        uint256 currentSupply = totalSupply();
        if (currentSupply == 0) {
            // If there's no supply, the reserves should ideally be zero.
            // A 100% backing is a reasonable representation in this state.
            return 1e18;
        }
        return totalBankReserves.mul(1e18).div(currentSupply);
    }
}


/**
 * @title Crypto UPI Hook
 * @author Expert Solidity Engineer
 * @notice A Uniswap v4 hook that enables users to withdraw INRT for fiat INR via UPI.
 * @dev This hook intercepts a "swap" of INRT, burns the tokens, and logs a withdrawal
 * request on the INRT contract, which a backend system can then process.
 */
contract CryptoUPIHook is BaseHook, Ownable {

    /// @notice The address of the INRT token contract.
    IINRT public inrtToken;

    // --- Events ---

    event InrtTokenAddressSet(address indexed tokenAddress);

    // --- Constructor ---

    constructor() {}

    // --- Owner Functions ---

    /**
     * @notice Sets the address of the INRT token contract.
     * @param _tokenAddress The address of the INRT contract.
     */
    function setInrtTokenAddress(address _tokenAddress) external onlyOwner {
        require(_tokenAddress != address(0), "Hook: Zero address");
        inrtToken = IINRT(_tokenAddress);
        emit InrtTokenAddressSet(_tokenAddress);
    }

    // --- Hook Overrides ---

    /**
     * @notice Specifies that this hook wants to execute logic before swaps.
     */
    function getHookPermissions() public pure override returns (uint160) {
        return Hooks.BEFORE_SWAP_FLAG;
    }

    /**
     * @notice This hook is called by the PoolManager before a swap.
     * @dev It checks if the swap is a sale of INRT. If so, it takes control of the
     * transaction flow by requesting a lock. Otherwise, it allows the swap to proceed.
     * @param sender The address that initiated the swap.
     * @param key The key identifying the Uniswap pool.
     * @param params The parameters of the swap.
     * @return A selector indicating the next action for the PoolManager.
     */
    function beforeSwap(address sender, PoolKey calldata key, IUniswapV4SwapCallback.SwapParams calldata params)
        public
        view
        override
        returns (bytes4)
    {
        bool isSellingINRT = (key.currency0 == address(inrtToken) && params.zeroForOne) ||
                              (key.currency1 == address(inrtToken) && !params.zeroForOne);

        // We only care about swaps where the user is selling INRT
        // and has specified a positive amount.
        if (isSellingINRT && params.amountSpecified > 0) {
            // Request a lock to take control of the transaction from the pool.
            return this.lockAcquired.selector;
        }

        // For all other swaps, do nothing.
        return super.beforeSwap(sender, key, params);
    }

    /**
     * @notice This function is called by the PoolManager after the hook requests a lock.
     * @dev It executes the withdrawal logic: transfers INRT from the user, then calls the
     * INRT contract to burn the tokens and create a withdrawal request.
     * @param data The encoded data from the initial `beforeSwap` call context.
     * @return An empty bytes string, as no further data is returned to the manager.
     */
    function lockAcquired(bytes calldata data) public override poolManagerOnly returns (bytes memory) {
        // Decode the original call data to get sender, amount, and hookData.
        (address sender, , IUniswapV4SwapCallback.SwapParams memory params, bytes memory hookData) =
            abi.decode(data, (address, PoolKey, IUniswapV4SwapCallback.SwapParams, bytes));

        // Decode the UPI ID from the hookData provided by the user.
        string memory upiId = abi.decode(hookData, (string));
        uint256 amountToWithdraw = uint256(params.amountSpecified);

        require(amountToWithdraw > 0, "Hook: Withdrawal amount must be positive");

        // Step 1: Transfer the user's INRT to this hook contract.
        // This implicitly checks and uses the allowance the user has given this hook.
        ERC20(address(inrtToken)).transferFrom(sender, address(this), amountToWithdraw);

        // Step 2: Call the INRT contract to burn the tokens and log the withdrawal.
        inrtToken.submitWithdrawal(sender, amountToWithdraw, upiId);

        return "";
    }
}

